HK = ['key:Escape', 'user:supervisor', 'click:menutop:Housekeeping & Maintenance', 'click:menuleaf:Housekeeping']
chapter(9, 'Housekeeping', 'Run the housekeeping board: tasks, assigning, cleaning with the checklist, inspection, reporting a repair and logging a found item. No hotel money is shown to housekeeping.',
        'Neha (Supervisor)', 'supervisor', menu='Housekeeping & Maintenance > Housekeeping')
step('It is 26 October. Neha, the housekeeping supervisor, starts on Modules Home. She has no Front Desk or Cash & Billing tile, only the modules her work needs.', 'Housekeeping and maintenance staff never see the hotel\'s money (rule DEC-061).',
     target='sel:.fit-home-grid', auto=['key:Escape', 'user:supervisor'], action='read', expect='Modules Home for Neha: Housekeeping & Maintenance, Guests & Services, Revenue & Sales, Stock & Purchasing, People & Payroll, Admin & Setup.', check="ctx.uid==='supervisor'")
tile('Housekeeping & Maintenance', 'Click the Housekeeping & Maintenance tile.', 'The board, work orders and the shift handover are in this module.', expect='The module page opens.')
leaf('Housekeeping & Maintenance', 'Housekeeping', 'Click the Housekeeping tile.', 'This is the board the whole housekeeping team works from.', expect='The Housekeeping board opens.', check="ctx.page==='housekeeping'")
read('The board has four columns: To do, In progress, Awaiting inspection and Done, and a panel showing each attendant\'s load. Each card is a room with its task, zone, standard minutes and assignee. There is no price or amount anywhere.',
     'The load panel tells the supervisor who has too many rooms.', target='sel:main h1', expect='The board with the task columns.')
pick('field:Assignee', 'Ravi', 'Use the Assignee filter and choose Ravi.', 'A supervisor can look at one attendant\'s work at a time.', expect='Only Ravi\'s rooms are listed.')
pick('field:Assignee', 'Everyone', 'Choose Everyone again.', 'Return filters to the full view before you leave the screen.', expect='All tasks are shown.')
read('Room 203 was left by Rahul Deshmukh and sits in the To do column. Every card has an assignee drop-down; the supervisor can give the room to another attendant there.', 'Moving a task balances the day without telling anyone twice.', target='btnin:Room 203|Start cleaning', expect='Room 203 is in the To do column.')
step('Ravi, the room attendant, opens the same page on his own login. He opens Housekeeping, finds room 203 and clicks Start cleaning.', 'Starting a task starts its timer; attendants see only their own tasks.', target='btnin:Room 203|Complete cleaning',
     auto=['user:housekeeper', 'click:menutop:Housekeeping & Maintenance', 'click:menuleaf:Housekeeping', 'click:btnin:Room 203|Start cleaning'], action='click', expect='Room 203 moves to In progress with a three-item checklist.', check="has('Final room check')")
step('Tick the three checklist items: Linen & bathroom, Surfaces & amenities and Final room check.', 'Complete cleaning stays grey until every item is ticked, so no step is skipped.', target='btnin:Room 203|Complete cleaning',
     auto=['check:fldin:Room 203|Linen & bathroom', 'check:fldin:Room 203|Surfaces & amenities', 'check:fldin:Room 203|Final room check'], action='click', expect='All three items are ticked.')
click('btnin:Room 203|Complete cleaning', 'Click Complete cleaning.', 'The room now waits for the supervisor\'s inspection; it cannot be sold before that.', expect='Room 203 moves to Awaiting inspection.')
step('Neha opens the board again. Room 203 and room 303 wait for inspection. Click Inspect & release on room 203.', 'An inspection by a second person is what makes a room Ready.', target='btnin:Room 203|Inspect & release',
     auto=HK, action='click', expect='Rooms 203 and 303 show Inspect & release.', check="has('Inspect & release')")
click('btnin:Room 203|Inspect & release', 'Click Inspect & release.', 'The room becomes Ready and appears as available on the Room board and in new reservations.', expect='Room 203 is Ready and leaves the board.')
click('btnin:Room 303|Return for cleaning', 'For room 303 the supervisor finds a stain and clicks Return for cleaning.', 'A failed inspection sends the room back to the attendant; it stays unsellable.', expect='A reason box asks why.')
step('Describe the problem and send it back. In the training Neha writes: Bathroom floor not clean.', 'The reason tells the attendant what to fix.', target='dialog:', auto=['type:field:Reason|Bathroom floor not clean'], action='type', expect='The reason is filled.')
click('modalbtn:Return', 'Click the button that returns the room.', 'The task goes back to To do for the same attendant.', expect='Room 303 is back in To do.')
click('btnin:Room 107|Report repair', 'On the card of room 107 click Report repair. Rahul reported the air conditioner of the room he left as noisy.', 'Housekeeping sees faults first; reporting them starts the maintenance work.', expect='The Report a repair dialog opens.', check="has('Report a repair')")
typ('field:What needs repair', 'Air conditioner noisy, compressor rattle', 'Describe the fault: Air conditioner noisy, compressor rattle.', 'The maintenance team reads this text, so be specific.', expect='The fault is described.')
click('modalbtn:Report repair', 'Click Report repair.', 'A repair request is created for Maintenance; chapter 10 follows it up.', expect='The repair is reported.')
step('Click Room details on any card, for example room 105, to see its drawer.', 'From the drawer a supervisor can also block the room for repair.', target='dialog:', auto=['click:btnin:Room 105|Room details'], action='click', expect='The room 105 drawer opens with Report repair and Block for repair.')
step('Close the drawer. Ravi found a phone charger in room 105 after Ms. Anita Rao left. He opens Guests & Services, My guest requests and clicks Log found item.', 'Everything found is logged with the room and where it is kept.', target='dialog:',
     auto=['key:Escape', 'user:housekeeper', 'click:menutop:Guests & Services', 'click:btn:Log found item'], action='click', expect='The Log a found item dialog opens.', check="has('Log item')")
step('Type the item Phone charger, choose the category Electronics, the room 105 and the storage Front office safe.', 'Reception returns found items from the register and matches them with a guest.', target='field:Item',
     auto=['type:field:Item|Phone charger', 'select:field:Category|Electronics', 'select:field:Room|105', 'select:field:Storage location|Front office safe'], action='type', expect='The form is filled.')
click('modalbtn:Log item', 'Click Log item.', 'The item is on the Lost & found list for reception.', expect='The found item is logged.')
step('Back as Aarav at Reception, open Guest services, the Lost & found tab, to see the item and the complaints list.', 'Reception does the returns and answers the complaints.', target='tab:Lost & found',
     auto=['user:reception', 'menu:Guests & Services>Guest services', 'click:tab:Lost & found'], action='click', expect='The Lost & found list shows the phone charger.')
click('tab:Complaints', 'Open the Complaints tab to see the air-conditioner complaint of chapter 4.', 'A complaint stays open until it is resolved and the guest has been answered.', expect='The complaints list is shown.')
